SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, COUNT(DISTINCT a.deathtime) AS death_count, SUM(CASE WHEN a.deathtime BETWEEN (CURRENT_DATE - INTERVAL '90 days') AND CURRENT_DATE THEN 1 ELSE 0 END) AS recent_death_count, SUM(CASE WHEN p.gender = 'F' AND p.anchor_age BETWEEN 70 AND 80 THEN 1 ELSE 0 END) AS recent_female_death_count, SUM(CASE WHEN d.icd_code = '4570' THEN 1 ELSE 0 END) AS aki_count, SUM(CASE WHEN d.icd_code = '4571' THEN 1 ELSE 0 END) AS ards_count, AVG(a.los) AS average_los FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 75 AND 76 AND d.icd_code = '4570' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version ORDER BY recent_female_death_count DESC, aki_count DESC, ards_count DESC, average_los DESC;